import{_ as t,o as d,c as r,ag as o}from"./chunks/framework.NIGIbcGl.js";const h=JSON.parse('{"title":"BlockSeat Route Pricing Guide (Admin)","description":"","frontmatter":{},"headers":[],"relativePath":"admin/blockseat-route-price/index.md","filePath":"admin/blockseat-route-price/index.md"}'),a={name:"admin/blockseat-route-price/index.md"};function i(c,e,s,n,l,p){return d(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="blockseat-route-pricing-guide-admin" tabindex="-1">BlockSeat Route Pricing Guide (Admin) <a class="header-anchor" href="#blockseat-route-pricing-guide-admin" aria-label="Permalink to &quot;BlockSeat Route Pricing Guide (Admin)&quot;">​</a></h1><p>Manage the <strong>per-route reducer</strong> that drives BlockSeat (wholesale) pricing. This is a <strong>lean, dedicated</strong> config — separate from <a href="/ahlaan-train-docs/admin/custom-route-price/">Custom Route Pricing</a> — so wholesale reducers never collide with promo reducers on the same <code>(origin, destination, tripClass)</code> key. It holds <strong>only</strong> the reducer concern (no selling-price / scraper / markup / tax machinery).</p><p>The BlockSeat payable for <strong>every</strong> cabin class is <code>supplier price − priceReducer</code> (see the <a href="/ahlaan-train-docs/customer/blockseat-ota/">BlockSeat OTA Guide</a>). A route with no active row prices at the raw supplier fare (reducer <code>0</code>).</p><hr><h2 id="quick-overview" tabindex="-1">Quick Overview <a class="header-anchor" href="#quick-overview" aria-label="Permalink to &quot;Quick Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>Per-route SAR reducer subtracted from the supplier price for BlockSeat</td></tr><tr><td><strong>Scope</strong></td><td><code>(originId, destinationId, tripClass, tripType)</code> — unique; symmetric (DMX↔MKX)</td></tr><tr><td><strong>Applies to</strong></td><td>ALL cabin classes (ECONOMY and BUSINESS)</td></tr><tr><td><strong>Lookup</strong></td><td>ROUND_TRIP treats each leg as ONE_WAY; rows are stored ONE_WAY</td></tr></tbody></table><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><p>All require admin JWT (<code>@Roles(ADMIN)</code>).</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/v1/admin/blockseat-route-prices</code></td><td>Create a reducer row. <code>originId</code>/<code>destinationId</code> are Location UUIDs; unique + reverse-direction guarded.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/admin/blockseat-route-prices</code></td><td>List with filters (route, class, type, isActive) + pagination.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/admin/blockseat-route-prices/:id</code></td><td>Get one.</td></tr><tr><td><code>PATCH</code></td><td><code>/api/v1/admin/blockseat-route-prices/:id</code></td><td>Update (route/class/type/capitalPrice/priceReducer/isActive).</td></tr><tr><td><code>DELETE</code></td><td><code>/api/v1/admin/blockseat-route-prices/:id</code></td><td>Soft-delete (sets <code>isActive = false</code>).</td></tr></tbody></table><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Notes</th></tr></thead><tbody><tr><td><code>originId</code>, <code>destinationId</code></td><td>Location UUIDs (real FKs, like CustomRoutePrice).</td></tr><tr><td><code>tripClass</code>, <code>tripType</code></td><td><code>ECONOMY</code>/<code>BUSINESS</code>, <code>ONE_WAY</code>/<code>ROUND_TRIP</code>.</td></tr><tr><td><code>capitalPrice</code></td><td>Admin cost reference for margin tracking (optional, default 0).</td></tr><tr><td><code>priceReducer</code></td><td>SAR subtracted from the supplier price (required).</td></tr><tr><td><code>isActive</code></td><td>Master toggle; only active rows are honored at pricing time.</td></tr></tbody></table><p>All mutations write an audit log (<code>BLOCKSEAT_ROUTE_PRICE_*</code>) and invalidate the route&#39;s reducer cache.</p>',12)])])}const m=t(a,[["render",i]]);export{h as __pageData,m as default};
